{
  "name": "DecaDAC多通道数模转换电压源",
  "name_en": "DecaDAC Multi-Channel DAC Voltage Source",
  "manufacturer": "Harvard",
  "description": "DecaDAC是一种多通道数模转换电压源，可输出可编程直流电压，并支持通道统一设定、斜坡扫描、触发和脚本序列控制。它常用于实验室中为器件提供偏置电压、进行参数扫描，以及执行需要多路稳定电压输出的自动化测量。",
  "description_en": "The DecaDAC is a multi-channel digital-to-analog voltage source that provides programmable DC outputs and supports global channel setting, voltage ramping, triggering, and scripted sequences. It is commonly used in laboratories to bias devices, perform parameter sweeps, and automate measurements requiring multiple stable voltage outputs.",
  "tag_hints": [
    "multi-channel DAC",
    "programmable voltage source",
    "DC biasing",
    "voltage ramping",
    "triggered sequences",
    "automated measurements"
  ],
  "actions": [
    {
      "action_name": "auto-start_script",
      "description": "开始设备脚本编辑或录制流程。",
      "description_en": "Start the device script editing or recording sequence."
    },
    {
      "action_name": "auto-end_script",
      "description": "结束设备脚本编辑或录制流程。",
      "description_en": "End the device script editing or recording sequence."
    },
    {
      "action_name": "auto-run_script",
      "description": "运行设备中已定义的脚本序列。",
      "description_en": "Run a previously defined script sequence on the device."
    },
    {
      "action_name": "auto-trigger",
      "description": "向设备施加触发设置以启动触发相关操作。",
      "description_en": "Apply a trigger setting to initiate trigger-related device behavior."
    },
    {
      "action_name": "auto-set_all",
      "description": "将所有DAC通道设为同一目标电压。",
      "description_en": "Set all DAC channels to the same target voltage."
    },
    {
      "action_name": "auto-ramp_all",
      "description": "以指定斜坡速率将所有DAC通道同时扫向目标电压。",
      "description_en": "Ramp all DAC channels toward a target voltage at the specified ramp rate."
    },
    {
      "action_name": "auto-connect_message",
      "description": "显示设备连接与识别信息摘要。",
      "description_en": "Display a summary of device connection and identification information."
    },
    {
      "action_name": "auto-write",
      "description": "向设备发送原始控制命令。",
      "description_en": "Send a raw control command to the device."
    },
    {
      "action_name": "auto-ask",
      "description": "向设备发送原始查询并读取返回结果。",
      "description_en": "Send a raw query to the device and read back the response."
    },
    {
      "action_name": "auto-get_idn",
      "description": "获取设备识别信息。",
      "description_en": "Get device identification information."
    }
  ]
}

